import numpy as np
from scipy.optimize import minimize

def objective(a):
    return -np.sum(a**2)

def constraint_sum_cubes(a):
    return np.sum(a**3)

def solve_for_n(n):
    # Bounds: a_i <= 2/sqrt(n)
    bounds = [(-None, 2/np.sqrt(n))] * n
    cons = {'type': 'eq', 'fun': constraint_sum_cubes}

    best_s = 0
    # Try multiple random starts
    for _ in range(20):
        a0 = np.random.uniform(-2, 2, n)
        res = minimize(objective, a0, method='SLSQP', bounds=bounds, constraints=cons)
        if res.success:
            best_s = max(best_s, -res.fun)
    return best_s

for n in range(2, 11):
    print(f"n={n}, max_S={solve_for_n(n)}")

import numpy as np
from scipy.optimize import minimize

def objective(a):
    return -np.sum(a**2)

def constraint_sum_cubes(a):
    return np.sum(a**3)

def solve_for_n(n):
    bounds = [(None, 2/np.sqrt(n))] * n
    cons = {'type': 'eq', 'fun': constraint_sum_cubes}

    best_s = 0
    # Try a few structured starts: some at bound, some negative
    for k in range(1, n):
        a0 = np.zeros(n)
        a0[:k] = 2/np.sqrt(n)
        # find x such that k(2/sqrt(n))^3 + (n-k)x^3 = 0
        x = - (k * (2/np.sqrt(n))**3 / (n-k))**(1/3)
        a0[k:] = x
        res = minimize(objective, a0, method='SLSQP', bounds=bounds, constraints=cons)
        if res.success:
            best_s = max(best_s, -res.fun)

    return best_s

for n in range(2, 11):
    print(f"n={n}, max_S={solve_for_n(n)}")
